package dev.zomboidmelee.boxing;
import java.util.*;
public final class Client20{
 static final Map<Object,State>STATES=new WeakHashMap<>();static Object world;static boolean pushing;
 static final class State{int kind,combo=-1;long start,contact,deniedUntil;boolean searching,hit;long resolved;double reach,height,side;int target=-1;}
 static State state(Object p){return STATES.computeIfAbsent(p,k->new State());}
 static long now(){return BoxingClient16.CLOCK.getAsLong();}
 public static void begin(Object p,int kind,boolean confirmed){State s=state(p);long n=now();if(!confirmed&&n<s.deniedUntil)return;if(s.kind==kind&&s.start!=0&&n-s.start<(confirmed?Motion20.duration(kind):60_000_000L))return;s.kind=kind;s.start=n;s.combo++;s.contact=0;StompClient21.begin(p,kind,confirmed);if(!confirmed&&kind==Motion20.LIGHT&&p==R.get(BoxingClient16.mc(),"player"))R.call(p,"playSound",R.get(R.type("net.minecraft.sounds.SoundEvents"),"PLAYER_ATTACK_SWEEP"),.25f,1.4f);}
 public static int kind(Object p){return state(p).kind;}
 public static boolean search(Object p){return state(p).searching;}
 public static double phase(Object p){State s=state(p);if(s.start==0)return 1;double raw=(now()-s.start)/(double)Motion20.duration(s.kind);return s.kind==Motion20.STOMP?StompClient21.phase(s,now(),raw):raw;}
 public static void tick(){Object m=BoxingClient16.mc(),p=R.get(m,"player"),level=R.get(m,"level");if(world!=level){world=level;STATES.clear();pushing=false;}if(p==null)return;boolean push=R.num(R.call(R.type("dev.zomboidmelee.combat.PushClient"),"wave",p,0f))>0;if(push&&!pushing)begin(p,Motion20.SHOVE,false);pushing=push;}
 public static void receive(int id,int action){Object m=BoxingClient16.mc(),level=R.get(m,"level");if(level==null||action<10||action>21)return;Object p=R.call(level,"getEntity",id);if(p==null)return;State s=state(p);if(StompClient21.receive(p,action))return;if(action==19){s.start=0;s.contact=0;s.deniedUntil=now()+400_000_000L;if(p==R.get(m,"player"))R.call(p,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"translatable","zomboid_global_melee.exhausted"),true);return;}if(action==14||action==15){s.searching=action==14;return;}if(action>=16){long intended=s.start+(long)(Motion20.impact(s.kind)*Motion20.duration(s.kind));s.contact=Math.max(now(),intended);return;}begin(p,action-10,true);}
 public static void camera(Object event){Object m=BoxingClient16.mc(),p=R.get(m,"player");if(p==null||R.get(m,"screen")!=null||!R.yes(R.call(p,"isAlive")))return;State s=state(p);if(!Boxing16.empty(p)&&s.kind!=Motion20.SHOVE)return;try{if(!Action19.firstPerson(m))return;}catch(IllegalStateException ignored){}double phase=phase(p);if(phase<0||phase>=1)return;if(s.kind==Motion20.STOMP){StompClient21.camera(event,p,phase);return;}double a=Motion20.strike(s.kind,phase),gain=s.kind==Motion20.HEAVY?1.65:s.kind==Motion20.STOMP?2.7:s.kind==Motion20.SHOVE?1.25:.70;double impulse=s.contact==0?0:Motion20.camera((now()-s.contact)/1e9)*gain;double pitch=(s.kind==Motion20.STOMP?Motion20.stamp(phase)*1.3:a*.26*gain)+impulse;double roll=(s.combo%2==0?1:-1)*(a*.15*gain+impulse*.20);R.call(event,"setPitch",((Number)R.call(event,"getPitch")).floatValue()+(float)pitch);R.call(event,"setRoll",((Number)R.call(event,"getRoll")).floatValue()+(float)roll);}
 public static void weaponShove(Object p,float partial,Object pose){double phase=phase(p),a=Motion20.strike(Motion20.SHOVE,phase);R.call(pose,"translate",-.07*a,.05*a,-.30*a);BoxingClient16.rotate(pose,"XP",-8*a);BoxingClient16.rotate(pose,"YP",-10*a);}
 public static void body(Object model,Object p){State s=state(p);double phase=phase(p);if(s.searching){Render20.body(model,Motion20.SEARCH,(now()%1_600_000_000L)/1_600_000_000.0,s.combo);return;}if(phase<1)Render20.body(model,s.kind,phase,Hands21.offEmpty(p)?s.combo:0);}
}
